public class SplitJoinDemo {
    public static void main(String[] args) {
        // 1. Splitting with escaped pipe delimiter
        String employeeRecord = "E104|Sarah Connor|DevOps|95000";
        String[] fields = employeeRecord.split("\\|");

        System.out.println("Field count: " + fields.length);
        System.out.println("ID: " + fields[0]);
        System.out.println("Name: " + fields[1]);
        System.out.println("Dept: " + fields[2]);
        System.out.println("Salary: " + fields[3]);

        // 2. Joining with custom delimiter
        String jsonFormat = String.join(" - ", fields);
        System.out.println("Formatted: " + jsonFormat);

        // 3. Splitting by comma
        String techStack = "Java,Spring,PostgreSQL,Docker";
        String[] techs = techStack.split(",");
        for (String tech : techs) {
            System.out.println("Tech: " + tech);
        }

        // 4. Splitting filename by dot (escaped)
        String file = "archive.tar.gz";
        String[] parts = file.split("\\.");
        System.out.println("File parts count: " + parts.length); // 3: archive, tar, gz

        // 5. Preserving trailing empty tokens with limit -1
        String sparse = "one,two,,";
        String[] defaultSplit = sparse.split(",");     // Drops trailing empties (length 2)
        String[] fullSplit = sparse.split(",", -1);    // Preserves trailing empties (length 4)
        System.out.println("Default split length: " + defaultSplit.length);
        System.out.println("Full split length: " + fullSplit.length);
    }
}

