practiceProblems.solutionCode:
public class MetricParser {
    public static void main(String[] args) {
        String metric = "srv-app-01|CPU|87.4|CRITICAL";
        String[] tokens = metric.split("\\|");
        System.out.println("Server: " + tokens[0]);
        System.out.println("Status: " + tokens[3]);
        double cpu = Double.parseDouble(tokens[2]);
        System.out.println("CPU Usage: " + cpu + "%");
    }
}

